import type { Storeshot } from '../../src/index.js';
import type { OperationId } from '../../src/generated/operations.js';

export const ID = '00000000-0000-4000-8000-000000000001';

/** One call per operation through its mapped method (`Record<OperationId, …>`: complete). */
export const CALLS: Record<OperationId, (client: Storeshot) => Promise<unknown>> = {
  addProjectItems: (c) => c.projects.addItems(ID, { generationIds: [ID] }),
  cancelBillingSubscription: (c) => c.billing.cancelSubscription(),
  cancelGeneration: (c) => c.generations.cancel(ID),
  cancelScreenshotSet: (c) => c.screenshotSets.cancel(ID),
  changeBillingSubscription: (c) => c.billing.changeSubscription({ plan: 'pro' }),
  completeUpload: (c) => c.uploads.complete(ID),
  createApiKey: (c) => c.apiKeys.create({ name: 'ci', environment: 'test' }),
  createBillingCheckout: (c) => c.billing.createCheckout({ pack: 'credits_15' }),
  createBillingPortalSession: (c) => c.billing.createPortalSession(),
  createBillingSubscriptionCheckout: (c) => c.billing.createSubscriptionCheckout({ plan: 'pro' }),
  createDeviceAuthorization: (c) => c.auth.startDeviceAuthorization({ clientName: 'ci' }),
  createDeviceToken: (c) => c.auth.pollDeviceToken('D'.repeat(43)),
  createGeneration: (c) =>
    c.generations.create({
      inputs: [{ uploadId: ID }],
      store: 'app_store',
      device: 'app_store_1290x2796',
      app: { name: 'Trailmate' },
    }),
  createPalette: (c) => c.palettes.create({ mode: 'extract', inputs: [{ uploadId: ID }] }),
  createProject: (c) => c.projects.create({ name: 'Trailmate' }),
  createScreenshotSet: (c) =>
    c.screenshotSets.create({
      app: { name: 'Trailmate' },
      screens: [{ input: { uploadId: ID }, caption: 'Find every trail' }],
      stores: [{ store: 'app_store' }],
    }),
  createUpload: (c) => c.uploads.create({ file: new Uint8Array([0x89, 0x50, 0x4e, 0x47]) }),
  createWebhook: (c) =>
    c.webhooks.create({ url: 'https://example.com/hook', events: ['generation.succeeded'] }),
  deleteGeneration: (c) => c.generations.delete(ID),
  deleteProject: (c) => c.projects.delete(ID),
  deleteScreenshotSet: (c) => c.screenshotSets.delete(ID),
  deleteUpload: (c) => c.uploads.delete(ID),
  deleteWebhook: (c) => c.webhooks.delete(ID),
  getBillingCheckout: (c) => c.billing.getCheckout(ID),
  getBillingSubscription: (c) => c.billing.getSubscription(),
  getCredits: (c) => c.credits.get(),
  getGeneration: (c) => c.generations.get(ID, { wait: 5 }),
  getHealth: (c) => c.health(),
  getMe: (c) => c.me(),
  getProject: (c) => c.projects.get(ID),
  getScreenshotSet: (c) => c.screenshotSets.get(ID),
  getScreenshotSetArchive: (c) => c.screenshotSets.archive(ID, { layout: 'fastlane' }),
  getStatus: (c) => c.status(),
  getStoreRequirements: (c) => c.stores.requirements('google_play'),
  getUpload: (c) => c.uploads.get(ID),
  getUsage: (c) => c.usage.get({ groupBy: 'source', from: '2026-10-01' }),
  getWebhook: (c) => c.webhooks.get(ID),
  listActivity: (c) => c.activity.list({ limit: 5 }),
  listApiKeys: (c) => c.apiKeys.list(),
  listBillingPacks: (c) => c.billing.listPacks(),
  listBillingPlans: (c) => c.billing.listPlans(),
  listDevices: (c) => c.devices.list({ store: 'app_store' }),
  listGenerations: (c) => c.generations.list({ limit: 10, status: 'succeeded', projectId: 'none' }),
  listProjects: (c) => c.projects.list({ limit: 10 }),
  listScreenshotSets: (c) => c.screenshotSets.list({ environment: 'test', status: 'running' }),
  listStores: (c) => c.stores.list(),
  listUploads: (c) => c.uploads.list({ cursor: 'abc' }),
  listWebhookDeliveries: (c) => c.webhooks.listDeliveries(ID, { status: 'failed' }),
  listWebhooks: (c) => c.webhooks.list({ environment: 'test' }),
  presignUpload: (c) => c.uploads.presign({ contentType: 'image/png', bytes: 1000 }),
  removeProjectItems: (c) => c.projects.removeItems(ID, { generationIds: [ID] }),
  retryScreenshotSet: (c) => c.screenshotSets.retry(ID),
  revokeApiKey: (c) => c.apiKeys.revoke(ID),
  rotateWebhookSecret: (c) => c.webhooks.rotateSecret(ID, { gracePeriodSeconds: 0 }),
  testWebhook: (c) => c.webhooks.test(ID),
  uncancelBillingSubscription: (c) => c.billing.uncancelSubscription(),
  updateProject: (c) => c.projects.update(ID, { name: 'Renamed' }),
  updateWebhook: (c) => c.webhooks.update(ID, { enabled: false }),
};
